import pandas as pd
import numpy as np
import matplotlib.pyplot as plt

def task_func(column, data):
    if not data:
        raise ValueError("The data list is empty.")

    df = pd.DataFrame(data)

    def _normalize(name):
        return str(name).strip().lower()

    normalized_columns = {}
    for original in df.columns:
        normalized_columns.setdefault(_normalize(original), original)

    if "date" not in normalized_columns:
        raise KeyError("Date")

    selected_norm = _normalize(column)
    if selected_norm not in normalized_columns or selected_norm == "date":
        raise KeyError(column)

    selected_col = normalized_columns[selected_norm]

    # Validate that the target column is numeric-convertible.
    try:
        selected_values = pd.to_numeric(df[selected_col], errors="raise")
    except Exception:
        raise KeyError(column) from None

    # Validate non-negativity for fitness metric columns if present.
    for metric in ("steps", "calories burned", "distance walked"):
        if metric in normalized_columns:
            metric_col = normalized_columns[metric]
            try:
                metric_values = pd.to_numeric(df[metric_col], errors="raise")
            except Exception:
                raise ValueError(
                    f"Column '{metric_col}' must contain numeric values."
                ) from None
            if (metric_values < 0).any():
                raise ValueError(
                    f"Column '{metric_col}' must not contain negative values."
                )

    date_col = normalized_columns["date"]

    stats = {
        "sum": selected_values.sum(),
        "mean": selected_values.mean(),
        "min": selected_values.min(),
        "max": selected_values.max(),
    }

    fig, ax = plt.subplots()
    ax.plot(df[date_col], selected_values, marker="o")
    ax.set_xlabel("Date")
    ax.set_ylabel(column)
    ax.set_title(f"Line Chart of ({column})")

    return stats, ax
